// Writes themes/default.css, stack.css, stack-plain.css, chart-patterns.svg and
// preview/src/lib/stack/design-values.ts from the front matter of DESIGN.md, and checks them.
//
//   node scripts/theme.mjs                     writes the five files
//   node scripts/theme.mjs --check [--staged]  exit 1 when a generated file differs, when another theme
//     file has another name set, when rounded.sm and rounded.md are not 0.5 and 0.75 of rounded.lg, when
//     theme-fallbacks is wrong, when a phone key is wrong, when a key of motion has no variable in
//     stack.css, when package.json would make a git install run a build, or when the list of
//     themes in the <head> script of preview/src/app.html and the files of themes/ disagree
//
// stack.css starts with one @source line for each folder of the package that holds Tailwind classes
// (SOURCES), so that a product that imports stack.css writes no @source line of its own.
//
// Each key of motion is the name of its Tailwind class. stack.css writes it in @theme, in the
// namespace that Tailwind 4 reads for that class: "duration-<name>" as --transition-duration-<name>,
// and "ease-<name>" as --ease-<name>. Tailwind makes no class from --duration-<name>. A duration is
// a number of ms, as breakpoints are numbers of px: the lint warns on an added key that holds a
// value such as "120ms" (token-like-ignored).
//
// Below breakpoints.md, stack.css changes the same text tokens to the "<step>-phone" values of
// typography, and gives each "<data-slot>-phone" key of components a min-height (from height or size)
// and a min-width (from width or size), in @layer base, so that a utility class of a product wins.
// A "typography" in a phone key gives the slot the font size and the line height of that type step,
// in @layer utilities after the utilities of Tailwind, because it must beat the text utility that the
// component itself carries. Four fixed rules follow: the touch target of the toast buttons, which set
// no data-slot (TOUCH_PARTS), the rule that stops the loops of the nova components (LOOPS), the looks
// that nova leaves to each page (looks()): a disabled link button at half strength, a dialog and an
// alert dialog that fill the screen below breakpoints.md, an empty state at the top left and the text of
// a toast, and the print rules of the kit (PRINT): a card stays on one page, a text area and a code
// block print their whole text, and an open dialog, alert dialog, sheet, drawer, dropdown menu, context
// menu or popover does not print.
//
// stack-plain.css holds the tokens of stack.css as plain custom properties, with the same names and
// values, for content that the build of a product never sees. It has no @theme, @layer or @apply,
// and no rule on an element: only :root, ":root, .dark" for the colors, and the phone steps of
// typography in a plain @media block.
//
// chart-patterns.svg holds the eight patterns of chart-patterns in the pattern style, for content with
// no CSS layer of STACK, such as a chart that a server draws as plain SVG for a printed document. The
// ids are stack-pattern-<n>, and the marks take currentColor. The geometry is the geometry of
// preview/src/lib/stack/StackPatternDefs.svelte in the pattern style (see "### Patterns" in DESIGN.md).
//
// preview/src/lib/stack/design-values.ts holds chart-patterns, spacing and theme-fallbacks as
// TypeScript values, for preview/src/lib/stack/patterns.ts, and the breakpoints, for
// preview/src/lib/stack/behaviour/width.ts. A file of the package reads these values there, so no
// file of the package reads DESIGN.md as text or needs the yaml package.
import { readdirSync, writeFileSync, mkdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { SHADCN_NAMES, readSource, readDesign, colorSets, parseThemeCss } from './lib/design.mjs';

const HEADER = '/* Generated by scripts/theme.mjs from the front matter of DESIGN.md. Do not edit it by hand: change DESIGN.md, then run "npm run theme". */';
const VALUES = 'preview/src/lib/stack/design-values.ts';
// The folders of the package whose files hold Tailwind classes. Tailwind skips node_modules, so a
// product that imports stack.css gets the classes of the components and the parts only through these
// lines. A path is relative to stack.css, so the lines hold in the repository and in node_modules.
const SOURCES = [
  '/* The classes of the components and the parts. Tailwind does not scan node_modules, so these lines name the folders of the package. */',
  ...['components/ui', 'stack', 'outside'].map((d) => `@source "./preview/src/lib/${d}";`),
];

// The type tokens of stack.css. Each Tailwind text size takes one typography token (decision on type).
const TEXT_TOKENS = [
  ['2xs', 'meta'],
  ['xs', 'small'],
  ['sm', 'body'],
  ['md', 'reading'],
  ['base', 'section'],
  ['xl', 'title'],
  ['3xl', 'figure'],
];

const px = (v, where) => {
  const m = /^(-?[\d.]+)px$/.exec(String(v));
  if (!m) throw new Error(`${where}: "${v}" must be a px value.`);
  return parseFloat(m[1]);
};
const rem = (n) => `${+(n / 16).toFixed(4)}rem`;
const indent = (n, lines) => lines.map((l) => `${' '.repeat(n)}${l}`);

const PHONE = '-phone';
// The properties of a phone key of components, and the declarations that each one writes.
const PHONE_PROPS = { height: ['min-height'], width: ['min-width'], size: ['min-height', 'min-width'], typography: ['font-size', 'line-height'] };
// The targets that set no data-slot, so that no phone key reaches them: the action, the cancel and the
// close button of a svelte-sonner toast. Below breakpoints.md each one takes spacing.touch as its
// min-height and min-width, next to the phone keys. svelte-sonner sets a height and a width and no
// minimum, so the minimum wins over its styles, which sit outside the layers.
const TOUCH_PARTS = ['[data-sonner-toast] [data-button]', '[data-sonner-toast] [data-close-button]'];
// The loops of the nova components. This file allows no loop, so a skeleton and the title of an
// attachment that uploads stay still in every mode, and a spinner stops under reduced motion. The rule
// sits in @layer utilities after the utilities of Tailwind, so that it beats animate-pulse, the shimmer
// utility and animate-spin on the same element. The shimmer utility reads --shimmer-image and
// --shimmer-text-fill, and the title selector matches its specificity.
const LOOPS = [
  '/* The loops of the nova components: a skeleton and the title of an attachment stay still, and a spinner stops under reduced motion. It comes after the utilities of Tailwind, so that it beats animate-pulse, the shimmer and animate-spin. */',
  '@layer utilities {',
  '  [data-slot=skeleton] {',
  '    animation: none;',
  '  }',
  '  [data-slot=attachment] [data-slot=attachment-title] {',
  '    --shimmer-image: none;',
  '    --shimmer-text-fill: currentColor;',
  '    animation: none;',
  '  }',
  '  @media (prefers-reduced-motion: reduce) {',
  '    .animate-spin {',
  '      animation: none;',
  '    }',
  '  }',
  '}',
  '',
];

// The looks that nova leaves to each page, so that a page gives no class for them. A link button with
// disabled renders aria-disabled="true" and no href, and nova draws only :disabled at 50%. The rule sits
// in @layer base, so that a utility class of a product wins. Below breakpoints.md a dialog and an alert
// dialog fill the screen: nova draws a box narrower than the screen in the middle. The four safe-area
// insets are a transparent border, not padding, so that the padding of the dialog stays, and no Tailwind
// class writes env(). An empty state is never centered: its content starts at the left edge,
// spacing.space-8 under the top of its region. Both rules sit in @layer utilities after the utilities of
// Tailwind. So they beat a class of the component with the same specificity, such as a width class of
// the content, because they come later, and a class with ! of a product still beats them. The width
// classes of an alert dialog also match [data-size], so the selector of the alert dialog has
// [data-size] too. The text of a toast takes the body step in font-sans, and its description
// muted-foreground. svelte-sonner writes its font on the toaster, so a rule on the toast beats it with
// no !important. svelte-sonner writes 13 px on the toast and a gray of its own on the description outside
// the layers, so only !important beats those two. The selectors are in :where(), so that a class with !
// that a product gives in toastOptions.classes still beats them.
function looks(front, phone) {
  const top = spacingRef(front, '{spacing.space-8}');
  const [body] = TEXT_TOKENS.find(([, token]) => token === 'body');
  return [
    '/* A link button of the kit with disabled: nova draws only :disabled at 50%, and the link has aria-disabled="true" and no href. It sits in the base layer, so that a utility class of a product wins. */',
    '@layer base {',
    '  a[data-slot=button][aria-disabled=true] {',
    '    opacity: 50%;',
    '  }',
    '}',
    '',
    `/* Below ${front.breakpoints?.md} px: a dialog and an alert dialog of the kit fill the screen, with the content at the top. The four safe-area insets are a transparent border, so that the padding of the dialog stays. It comes after the utilities of Tailwind, so that it beats the place, the width and the radius classes of the content. The width classes of an alert dialog match [data-size], so its selector has [data-size] too. */`,
    '@layer utilities {',
    `  ${phone} {`,
    '    [data-slot=dialog-content],',
    '    [data-slot=alert-dialog-content][data-size] {',
    '      inset: 0;',
    '      max-width: none;',
    '      translate: none;',
    '      border-radius: 0;',
    '      border-color: transparent;',
    '      border-width: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);',
    '      align-content: flex-start;',
    '    }',
    '  }',
    '}',
    '',
    `/* An empty state of the kit is never centered: its content starts at the left edge, ${px(top, 'spacing.space-8')} px under the top of its region. It comes after the utilities of Tailwind, so that it beats the center and the padding classes of the component. */`,
    '@layer utilities {',
    '  [data-slot=empty] {',
    '    align-items: flex-start;',
    '    justify-content: flex-start;',
    '    padding: 0;',
    `    padding-top: ${top};`,
    '    text-align: left;',
    '  }',
    '  [data-slot=empty-header],',
    '  [data-slot=empty-content] {',
    '    align-items: flex-start;',
    '  }',
    '}',
    '',
    '/* The text of a toast takes the body step in the sans font of the theme, and its description takes muted-foreground. svelte-sonner writes the size and the gray of the description outside the layers, so only !important beats those two. The selectors are in :where(), so that a class with ! of a product beats them. */',
    '@layer utilities {',
    '  :where([data-sonner-toast]) {',
    '    font-family: var(--font-sans);',
    `    font-size: var(--text-${body}) !important;`,
    `    line-height: var(--text-${body}--line-height);`,
    '  }',
    '  :where([data-sonner-toast] [data-description]) {',
    '    color: var(--color-muted-foreground) !important;',
    '  }',
    '}',
    '',
  ];
}

// The print rules of the kit. A product never edits a kit file, so the rules sit here. A card that
// does not fit at the end of a page moves to the next page. The rule sits in @layer base, so that a
// utility class of a product, such as print:break-inside-auto, wins. A text area of the kit grows with
// its text (field-sizing-content), and a product caps it with a class such as max-h-80, so that it
// scrolls on the screen. Paper cannot scroll, so in print the cap goes. That rule sits in @layer
// utilities after the utilities of Tailwind, because it must beat the max-h class of the product.
// textarea[data-slot] takes the textarea slot and the text area of an input-group, whose data-slot is
// input-group-control. A code block stops at max-h-80, or at the max-h class of the product, and then
// its text scrolls, so the same rule removes its cap. Its scroll box then breaks between two lines at
// the end of a page, so it needs no rule of its own. An open dialog, alert dialog, sheet, drawer,
// dropdown menu, context menu or popover holds a question or a task and not the content of the page,
// so in print it and the scrim of a dialog, an alert dialog, a sheet or a drawer do not show, and the
// page under them prints. A fixed layer printed on every page.
// That rule also sits in @layer utilities, because it must beat the display class of the content, grid
// or flex. The content of a select is not in the rule: Bits UI sets display: flex in its style
// attribute, which no rule of a layer beats. A checked check box draws its check in the color of the
// text on its fill, and the print drops the fill, so the box printed empty. In print the check takes
// foreground. That rule sits in @layer utilities too, because it must beat the text color class of
// the checked state, also a class at use.
const PRINT = [
  '/* In print: a card of the kit stays on one page. It sits in the base layer, so that a utility class of a product wins. */',
  '@layer base {',
  '  @media print {',
  '    [data-slot=card] {',
  '      break-inside: avoid;',
  '    }',
  '  }',
  '}',
  '',
  '/* In print: a text area and a code block of the kit print their whole text, because paper cannot scroll. It comes after the utilities of Tailwind, so that it beats a max-h class such as max-h-80. */',
  '@layer utilities {',
  '  @media print {',
  '    textarea[data-slot],',
  '    div[data-slot=code-block] {',
  '      max-height: none;',
  '    }',
  '  }',
  '}',
  '',
  '/* In print: an open dialog, alert dialog, sheet, drawer, dropdown menu, context menu or popover of the kit does not show, and neither does the scrim of a dialog, an alert dialog, a sheet or a drawer, so the page under them prints. It comes after the utilities of Tailwind, so that it beats the grid or flex class of the content. */',
  '@layer utilities {',
  '  @media print {',
  '    [data-slot=dialog-overlay],',
  '    [data-slot=dialog-content],',
  '    [data-slot=alert-dialog-overlay],',
  '    [data-slot=alert-dialog-content],',
  '    [data-slot=sheet-overlay],',
  '    [data-slot=sheet-content],',
  '    [data-slot=drawer-overlay],',
  '    [data-slot=drawer-content],',
  '    [data-slot=dropdown-menu-content],',
  '    [data-slot=context-menu-content],',
  '    [data-slot=popover-content] {',
  '      display: none;',
  '    }',
  '  }',
  '}',
  '',
  '/* In print: a checked check box of the kit draws its check in foreground, because the print drops its fill, and a check in the color of the text on the fill printed white on white. It comes after the utilities of Tailwind, so that it beats the text color class of the checked state. */',
  '@layer utilities {',
  '  @media print {',
  '    [data-slot=checkbox][data-state=checked] {',
  '      color: var(--color-foreground);',
  '    }',
  '  }',
  '}',
  '',
];

/** The custom properties of one text token: size, line height and the optional letter spacing. */
function textVars(size, t, where) {
  const out = [
    `--text-${size}: ${rem(px(t.fontSize, `${where}.fontSize`))};`,
    `--text-${size}--line-height: ${rem(px(t.lineHeight, `${where}.lineHeight`))};`,
  ];
  if (t.letterSpacing !== undefined) out.push(`--text-${size}--letter-spacing: ${t.letterSpacing};`);
  return out;
}

/** The font stacks of stack.css: font-sans from the body step, font-mono from the code step. */
function fontVars(typo) {
  return [`--font-sans: ${typo.body.fontFamily};`, `--font-mono: ${typo.code.fontFamily};`];
}

/** The width lines, as the Tailwind breakpoints. */
function breakpointVars(front) {
  return Object.entries(front.breakpoints ?? {}).map(([k, v]) => `--breakpoint-${k}: ${rem(v)};`);
}

// The radius levels, derived from the --radius of the theme: sm is 0.5 of it, md 0.75, lg to 4xl equal.
const RADIUS_VARS = [
  '--radius-sm: calc(var(--radius) * 0.5);',
  '--radius-md: calc(var(--radius) * 0.75);',
  ...['lg', 'xl', '2xl', '3xl', '4xl'].map((k) => `--radius-${k}: var(--radius);`),
];

/** Each color role as --color-<name>. An added role falls back to its theme-fallbacks value. */
function colorVars(front) {
  const fallbacks = front['theme-fallbacks'] ?? {};
  return [...colorSets(front).light.keys()].map((n) => {
    const fb = fallbacks[n];
    const value = fb === undefined ? `var(--${n})` : `var(--${n}, ${String(fb).startsWith('oklch(') ? fb : `var(--${fb})`})`;
    return `--color-${n}: ${value};`;
  });
}

// The class prefixes of a motion key, the Tailwind 4 namespace of each one, and the CSS value of a
// key, which is null when the value has the wrong form.
const MOTION = [
  { prefix: 'duration-', namespace: '--transition-duration-', css: (v) => (Number.isInteger(v) && v > 0 ? `${v}ms` : null), form: 'a whole number of ms, such as 120' },
  { prefix: 'ease-', namespace: '--ease-', css: (v) => (/^cubic-bezier\(\s*-?\d*\.?\d+(\s*,\s*-?\d*\.?\d+){3}\s*\)$/.test(String(v)) ? v : null), form: 'a cubic-bezier() string' },
];
const motionKind = (key) => MOTION.find((m) => key.startsWith(m.prefix) && /^[a-z0-9-]+$/.test(key.slice(m.prefix.length)));

/** The declaration of one motion key, such as "--transition-duration-fast: 120ms;". */
function motionDecl(key, value) {
  const m = motionKind(key);
  return `${m.namespace}${key.slice(m.prefix.length)}: ${m.css(value)};`;
}

/** The motion keys as Tailwind theme variables, in the order of the file. */
function motionVars(front) {
  return Object.entries(front.motion ?? {}).map(([k, v]) => motionDecl(k, v));
}

/** Problems of the keys and values of motion. Empty when stack.css can write them. */
function motionKeyProblems(front) {
  const problems = [];
  for (const [k, v] of Object.entries(front.motion ?? {})) {
    const m = motionKind(k);
    if (!m) problems.push(`motion.${k}: a key of motion is the name of its class and starts with ${MOTION.map((x) => `"${x.prefix}"`).join(' or ')}, such as "duration-fast" or "ease-stack".`);
    else if (m.css(v) === null) problems.push(`motion.${k}: "${v}" must be ${m.form}.`);
  }
  return problems;
}

/** Problems of a stack.css text: each key of motion needs its variable, with its value, in the @theme block. */
function motionProblems(front, css) {
  const block = /^@theme \{\n([\s\S]*?)\n\}/m.exec(css ?? '')?.[1].split('\n').map((l) => l.trim()) ?? [];
  return Object.entries(front.motion ?? {})
    .filter(([k, v]) => !block.includes(motionDecl(k, v)))
    .map(([k, v]) => `motion.${k}: the @theme block of stack.css has no "${motionDecl(k, v)}", so the class ${k} does not exist.`);
}

/** The text tokens of TEXT_TOKENS, from the type steps. */
function textTokenVars(typo) {
  return TEXT_TOKENS.flatMap(([size, token]) => {
    const t = typo[token];
    if (!t) throw new Error(`typography.${token} is missing; stack.css maps it to --text-${size}.`);
    return textVars(size, t, `typography.${token}`);
  });
}

/** The text tokens that change below breakpoints.md, from the "<step>-phone" keys. */
function phoneTextVars(typo) {
  return TEXT_TOKENS.filter(([, token]) => typo[token + PHONE])
    .flatMap(([size, token]) => textVars(size, typo[token + PHONE], `typography.${token}${PHONE}`));
}

// The weight names of Tailwind, so that var(--font-weight-semibold) in plain CSS is the class font-semibold.
const WEIGHT_NAMES = { 100: 'thin', 200: 'extralight', 300: 'light', 400: 'normal', 500: 'medium', 600: 'semibold', 700: 'bold', 800: 'extrabold', 900: 'black' };
// The Tailwind spacing step. stack.css keeps the default, so calc(var(--spacing) * 4) is the class p-4.
const TAILWIND_SPACING = '0.25rem';

/** The value of a "{spacing.<name>}" reference, or null when the reference does not resolve. */
function spacingRef(front, ref) {
  const m = /^\{spacing\.([a-z0-9-]+)\}$/.exec(String(ref));
  return m && front.spacing?.[m[1]] !== undefined ? front.spacing[m[1]] : null;
}

/** The type step of a "{typography.<name>}" reference, or null when the reference does not resolve. */
function typographyRef(front, ref) {
  const m = /^\{typography\.([a-z0-9-]+)\}$/.exec(String(ref));
  return m && front.typography?.[m[1]] !== undefined ? front.typography[m[1]] : null;
}

/** The declarations of one phone key: [property, value] pairs, the touch target and the type apart. */
function phoneDecls(front, key, where) {
  const target = new Map();
  const type = new Map();
  for (const [prop, ref] of Object.entries(key)) {
    if (prop === 'typography') {
      const t = typographyRef(front, ref);
      type.set('font-size', rem(px(t.fontSize, `${where}.fontSize`)));
      type.set('line-height', rem(px(t.lineHeight, `${where}.lineHeight`)));
    } else for (const d of PHONE_PROPS[prop]) target.set(d, spacingRef(front, ref));
  }
  return { target, type };
}

/** Problems of the phone keys of typography and components. Empty when stack.css can write them. */
function phoneProblems(front) {
  const problems = [];
  const typo = front.typography ?? {};
  const steps = TEXT_TOKENS.map(([, token]) => token);
  const typoKeys = Object.keys(typo).filter((k) => k.endsWith(PHONE));
  const compKeys = Object.keys(front.components ?? {}).filter((k) => k.endsWith(PHONE));
  if (typeof front.breakpoints?.md !== 'number') {
    problems.push('breakpoints.md must be a number: the phone keys and the targets of a toast apply below it.');
  }
  if (spacingRef(front, '{spacing.touch}') === null) {
    problems.push('spacing.touch must be set: stack.css gives it to the buttons of a toast below breakpoints.md.');
  }
  for (const k of typoKeys) {
    const step = k.slice(0, -PHONE.length);
    if (!steps.includes(step)) {
      problems.push(`typography.${k}: stack.css changes only these steps on a phone: ${steps.map((s) => s + PHONE).join(', ')}.`);
      continue;
    }
    for (const p of ['fontFamily', 'fontWeight']) {
      if (typo[k][p] !== typo[step]?.[p]) problems.push(`typography.${k}.${p} differs from typography.${step}.${p}. On a phone stack.css changes the size, the line height and the letter spacing only.`);
    }
  }
  for (const k of compKeys) {
    const slot = k.slice(0, -PHONE.length);
    if (!/^[a-z][a-z0-9-]*$/.test(slot)) problems.push(`components.${k}: "${slot}" is not a data-slot name.`);
    for (const [prop, ref] of Object.entries(front.components[k] ?? {})) {
      if (!PHONE_PROPS[prop]) problems.push(`components.${k}.${prop}: a phone key holds ${Object.keys(PHONE_PROPS).join(', ')} only, which stack.css writes as min-height, min-width, font-size and line-height.`);
      else if (prop === 'typography') {
        if (typographyRef(front, ref) === null) problems.push(`components.${k}.typography: "${ref}" must be a reference to a type step, such as "{typography.section}".`);
      } else if (spacingRef(front, ref) === null) problems.push(`components.${k}.${prop}: "${ref}" must be a reference to a spacing token, such as "{spacing.touch}".`);
    }
  }
  return problems;
}

/** The Theme tab form: a header comment, ":root" with "--radius" last, then ".dark". scripts/generate.mjs gives its own header. */
export function renderTheme(sets, radius, header = HEADER) {
  const names = [...sets.light.keys()];
  const block = (sel, map, extra) => [`${sel} {`, ...names.map((n) => `  --${n}: ${map.get(n)};`), ...extra, '}'].join('\n');
  return `${header}\n${block(':root', sets.light, [`  --radius: ${radius};`])}\n\n${block('.dark', sets.dark, [])}\n`;
}

/** The Tailwind layer that every product imports after preview/src/lib/components/ui/shadcn-svelte.css and before a theme. */
export function renderStackCss(front) {
  const typo = front.typography ?? {};
  const out = [HEADER, '', ...SOURCES, '', '@custom-variant dark (&:is(.dark *));', '', '@theme inline {'];
  out.push(...indent(2, [...fontVars(typo), ...breakpointVars(front), ...RADIUS_VARS, ...colorVars(front)]));
  out.push('}', '', '@theme {', ...indent(2, [...textTokenVars(typo), ...motionVars(front)]), '}', '');
  const phone = `@media (width < ${rem(front.breakpoints?.md ?? 0)})`;
  const phoneText = phoneTextVars(typo);
  if (phoneText.length) {
    out.push(`/* Below ${front.breakpoints.md} px: the phone steps of typography, as the same text tokens. */`, '@layer theme {', `  ${phone} {`, '    :root, :host {');
    out.push(...indent(6, phoneText), '    }', '  }', '}', '');
  }
  out.push('@layer base {', '  * {', '    @apply border-border outline-ring/50;', '  }', '  body {', '    @apply bg-background text-foreground;', '  }', '  html {', '    @apply font-sans;', '  }', '}', '');
  const touch = spacingRef(front, '{spacing.touch}');
  const keys = [
    ...Object.entries(front.components ?? {})
      .filter(([k]) => k.endsWith(PHONE))
      .map(([k, v]) => ({ selector: `[data-slot=${k.slice(0, -PHONE.length)}]`, ...phoneDecls(front, v, `components.${k}`) })),
    ...TOUCH_PARTS.map((selector) => ({ selector, target: new Map([['min-height', touch], ['min-width', touch]]), type: new Map() })),
  ];
  const block = (comment, layer, part) => {
    const list = keys.filter((x) => x[part].size);
    if (!list.length) return;
    out.push(comment, `@layer ${layer} {`, `  ${phone} {`);
    for (const x of list) out.push(`    ${x.selector} {`, ...[...x[part]].map(([d, val]) => `      ${d}: ${val};`), '    }');
    out.push('  }', '}', '');
  };
  block(`/* Below ${front.breakpoints?.md} px: the touch targets of the phone keys of components, and of the buttons of a toast, which set no data-slot. */`, 'base', 'target');
  block(`/* Below ${front.breakpoints?.md} px: the type of the phone keys of components. It comes after the utilities of Tailwind, so that it beats the text utility of the component. */`, 'utilities', 'type');
  out.push(...LOOPS, ...looks(front, phone), ...PRINT);
  return out.join('\n');
}

/**
 * The tokens of stack.css as plain custom properties, for a page or a fragment that no Tailwind
 * build reads. Same names and values as stack.css, plus two Tailwind defaults that a class reads
 * (the weights and the spacing step) and two token groups that stack.css does not write
 * (rounded.full and the spacing keys). The colors sit on ":root, .dark", so that a fragment under
 * a .dark element that is not <html> takes the dark value.
 */
export function renderPlainCss(front) {
  const typo = front.typography ?? {};
  const weights = [...new Set(Object.values(typo).map((t) => Number(t.fontWeight)))].sort((a, b) => a - b);
  for (const w of weights) {
    if (!WEIGHT_NAMES[w]) throw new Error(`typography: the weight ${w} has no Tailwind name. Use one of ${Object.keys(WEIGHT_NAMES).join(', ')}.`);
  }
  const tokens = [
    ...fontVars(typo),
    ...weights.map((w) => `--font-weight-${WEIGHT_NAMES[w]}: ${w};`),
    ...textTokenVars(typo),
    ...breakpointVars(front),
    ...RADIUS_VARS,
    `--radius-full: ${px(front.rounded?.full, 'rounded.full')}px;`,
    `--spacing: ${TAILWIND_SPACING};`,
    ...Object.entries(front.spacing ?? {}).map(([k, v]) => `--spacing-${k}: ${rem(px(v, `spacing.${k}`))};`),
    ...motionVars(front),
  ];
  const out = [
    HEADER,
    '/* The tokens of stack.css as plain custom properties, with the same names, for content that the build of a product never sees. Link a theme file first, then this file. A color is var(--color-<role>), and an opacity modifier is color-mix(in oklab, var(--color-<role>) <n>%, transparent). */',
    ':root {', ...indent(2, tokens), '}', '',
    ':root, .dark {', ...indent(2, colorVars(front)), '}',
  ];
  const phoneText = phoneTextVars(typo);
  if (phoneText.length) {
    out.push('', `/* Below ${front.breakpoints.md} px: the phone steps of typography, as the same text tokens. */`);
    out.push(`@media (width < ${rem(front.breakpoints.md)}) {`, '  :root {', ...indent(4, phoneText), '  }', '}');
  }
  return `${out.join('\n')}\n`;
}

const PATTERN_TYPES = ['lines', 'cross', 'dots', 'squares'];

/** Problems of chart-patterns. Empty when chart-patterns.svg can draw each entry. */
function patternProblems(front) {
  const patterns = front['chart-patterns'];
  if (!patterns || typeof patterns !== 'object') return ['chart-patterns is missing: chart-patterns.svg draws its patterns from it.'];
  if (Object.keys(patterns).length !== 8) return ['chart-patterns holds eight entries, pattern-1 to pattern-8.'];
  return Object.entries(patterns).flatMap(([name, p], i) => {
    const valid =
      name === `pattern-${i + 1}` &&
      PATTERN_TYPES.includes(p?.type) &&
      ['angle', 'width', 'pitch'].every((f) => Number.isFinite(p[f])) &&
      p.width > 0 &&
      p.pitch > 0 &&
      typeof p.stagger === 'boolean';
    return valid
      ? []
      : [`chart-patterns entry ${i + 1} must be named pattern-${i + 1} and hold type (${PATTERN_TYPES.join(', ')}), angle, width and pitch as numbers, width and pitch above 0, and stagger as true or false. It is ${name}: ${JSON.stringify(p)}.`];
  });
}

/**
 * The patterns of chart-patterns in the pattern style, as one <defs> in a 0 by 0 svg. Each mark takes
 * currentColor, so the marks take the color of the element around the svg. The center of a mark is
 * floor(pitch / 2) + (width mod 2) / 2, so that its edges fall on whole pixels at 1x. A staggered tile
 * is twice as high, and the mark of its second row sits at both vertical edges of the tile.
 */
export function renderPatternSvg(front) {
  const out = [
    '<!-- Generated by scripts/theme.mjs from chart-patterns in the front matter of DESIGN.md. Do not edit it by hand: change DESIGN.md, then run "npm run theme". The eight patterns of the pattern style, with the ids stack-pattern-1 to stack-pattern-8. Put this svg into the same document as the chart, and never hide it with display: none. Each mark takes currentColor. -->',
    '<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position: absolute" aria-hidden="true" focusable="false">',
    '  <defs>',
  ];
  Object.values(front['chart-patterns']).forEach((p, i) => {
    const h = p.stagger ? p.pitch * 2 : p.pitch;
    const c = Math.floor(p.pitch / 2) + (p.width % 2) / 2;
    const turn = p.angle ? ` patternTransform="rotate(${p.angle})"` : '';
    out.push(`    <pattern id="stack-pattern-${i + 1}" width="${p.pitch}" height="${h}" patternUnits="userSpaceOnUse"${turn}>`);
    const line = (x1, y1, x2, y2) => `      <line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="currentColor" stroke-width="${p.width}" />`;
    if (p.type === 'lines' || p.type === 'cross') {
      out.push(line(c, 0, c, h));
      if (p.type === 'cross') out.push(line(0, c, p.pitch, c));
    } else {
      const shifted = c + p.pitch / 2;
      const marks = p.stagger ? [[c, c], [shifted, c + p.pitch], [shifted - p.pitch, c + p.pitch]] : [[c, c]];
      for (const [x, y] of marks) {
        out.push(
          p.type === 'dots'
            ? `      <circle cx="${x}" cy="${y}" r="${p.width / 2}" fill="currentColor" />`
            : `      <rect x="${x - p.width / 2}" y="${y - p.width / 2}" width="${p.width}" height="${p.width}" fill="currentColor" />`,
        );
      }
    }
    out.push('    </pattern>');
  });
  out.push('  </defs>', '</svg>', '');
  return out.join('\n');
}

/** A string or a number of the front matter as a TypeScript literal, and a key as a property name. */
const literal = (v) => (typeof v === 'string' ? `'${v.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'` : String(v));
const property = (k) => (/^[A-Za-z_$][\w$]*$/.test(k) ? k : literal(k));
const entries = (obj, value) => Object.entries(obj).map(([k, v]) => `\t${property(k)}: ${value(v)},`);

/**
 * The values of the front matter that preview/src/lib/stack/patterns.ts reads: chart-patterns,
 * spacing and theme-fallbacks. The types are the types that the preview gave them when it read
 * DESIGN.md with the yaml package.
 */
export function renderDesignValues(front) {
  const pattern = (p) => `{ ${['type', 'angle', 'width', 'pitch', 'stagger'].map((f) => `${f}: ${literal(p[f])}`).join(', ')} }`;
  return [
    '// Generated by scripts/theme.mjs from the front matter of DESIGN.md. Do not edit it by hand: change DESIGN.md, then run "npm run theme".',
    '// The values that the chart patterns read. A file of the package reads them here, so it reads no DESIGN.md and needs no yaml package.',
    '',
    '/** One entry of chart-patterns (see "### Patterns" in DESIGN.md). */',
    'export type ChartPattern = {',
    `\ttype: ${PATTERN_TYPES.map(literal).join(' | ')};`,
    '\tangle: number;',
    '\twidth: number;',
    '\tpitch: number;',
    '\tstagger: boolean;',
    '};',
    '',
    '/** chart-patterns: pattern-1 to pattern-8. */',
    'export const chartPatterns: Record<string, ChartPattern> = {',
    ...entries(front['chart-patterns'], pattern),
    '};',
    '',
    '/** spacing. */',
    'export const spacing: Record<string, string> = {',
    ...entries(front.spacing ?? {}, literal),
    '};',
    '',
    '/** theme-fallbacks. */',
    'export const themeFallbacks: Record<string, string> = {',
    ...entries(front['theme-fallbacks'] ?? {}, literal),
    '};',
    '',
    '/** breakpoints: the width line of each band in px (see "### Width bands" in DESIGN.md). behaviour/width.ts reads them. */',
    'export const breakpoints = {',
    ...entries(front.breakpoints ?? {}, literal),
    '} as const;',
    '',
  ].join('\n');
}

/** Names that one block has and the other lacks, for :root and for .dark. */
export function diffNames(a, b) {
  return ['root', 'dark'].map((block) => ({
    block,
    missing: [...a[block].keys()].filter((n) => !b[block].has(n)),
    extra: [...b[block].keys()].filter((n) => !a[block].has(n)),
  }));
}

function render(front) {
  const sets = colorSets(front);
  const lg = px(front.rounded?.lg, 'rounded.lg');
  return { theme: renderTheme(sets, rem(lg)), stack: renderStackCss(front), plain: renderPlainCss(front), patterns: renderPatternSvg(front), values: renderDesignValues(front) };
}

function frontProblems(front) {
  const problems = [];
  const sets = colorSets(front);
  for (const mode of ['light', 'dark']) {
    for (const [n, v] of sets[mode]) {
      if (!/^oklch\(/.test(v)) problems.push(`colors${mode === 'dark' ? '.dark' : ''}.${n}: "${v}" is not an oklch() value.`);
    }
  }
  const r = front.rounded ?? {};
  const lg = px(r.lg, 'rounded.lg');
  if (px(r.sm, 'rounded.sm') !== lg * 0.5) problems.push(`rounded.sm is ${r.sm}; stack.css derives it as 0.5 of rounded.lg, which is ${lg * 0.5}px.`);
  if (px(r.md, 'rounded.md') !== lg * 0.75) problems.push(`rounded.md is ${r.md}; stack.css derives it as 0.75 of rounded.lg, which is ${lg * 0.75}px.`);
  const fallbacks = front['theme-fallbacks'] ?? {};
  for (const [n, target] of Object.entries(fallbacks)) {
    if (!sets.light.has(n)) problems.push(`theme-fallbacks.${n}: colors has no name "${n}".`);
    if (SHADCN_NAMES.includes(n)) problems.push(`theme-fallbacks.${n}: every theme sets "${n}", so it needs no fallback.`);
    const t = String(target);
    if (!t.startsWith('oklch(') && !SHADCN_NAMES.includes(t)) problems.push(`theme-fallbacks.${n}: "${t}" must be a name that every theme sets (${SHADCN_NAMES[0]}, ...) or an oklch() value.`);
  }
  for (const n of sets.light.keys()) {
    if (!SHADCN_NAMES.includes(n) && fallbacks[n] === undefined) problems.push(`theme-fallbacks has no entry for "${n}". A pasted theme lacks it, so stack.css needs a fallback.`);
  }
  const space8 = spacingRef(front, '{spacing.space-8}');
  if (space8 === null) problems.push('spacing.space-8 must be set: stack.css starts the content of an empty state that far under the top of its region.');
  else if (!/^[\d.]+px$/.test(String(space8))) problems.push(`spacing.space-8: "${space8}" must be a px value, such as "32px": stack.css starts the content of an empty state that far under the top of its region.`);
  problems.push(...phoneProblems(front), ...motionKeyProblems(front), ...patternProblems(front));
  return problems;
}

function packageProblems(text) {
  if (text === null) return ['package.json not found.'];
  const pkg = JSON.parse(text);
  const problems = [];
  if (pkg.workspaces) problems.push('package.json has "workspaces". A product that installs this git would then install the whole tree.');
  for (const s of ['prepare', 'prepack', 'build', 'install', 'preinstall', 'postinstall']) {
    if (pkg.scripts?.[s]) problems.push(`package.json has a "${s}" script. npm runs a full install for a git dependency with such a script, in every product.`);
  }
  return problems;
}

function themeFiles(staged) {
  if (staged) {
    const out = execFileSync('git', ['ls-files', '--', 'themes/'], { encoding: 'utf8' });
    return out.split('\n').filter((f) => /^themes\/[^/]+\.css$/.test(f));
  }
  try {
    return readdirSync('themes').filter((f) => f.endsWith('.css')).map((f) => `themes/${f}`);
  } catch {
    return [];
  }
}

// The <head> script of the preview links /themes/<name>.css before the first paint, and it checks
// the stored name against its own list of themes. A file that the list lacks never loads in the
// preview, and a name with no file loads nothing.
function previewThemeProblems(html, files) {
  const at = 'preview/src/app.html';
  if (html === null) return [`${at} not found.`];
  const m = /var themes = \[([^\]]*)\];/.exec(html);
  if (!m) return [`${at} has no line "var themes = [...];" in its <head> script.`];
  const listed = [...m[1].matchAll(/'([^']*)'/g)].map((x) => x[1]);
  const names = files.map((f) => f.slice('themes/'.length, -'.css'.length));
  const problems = [];
  const unlisted = names.filter((n) => !listed.includes(n));
  const fileless = listed.filter((n) => !names.includes(n));
  if (unlisted.length) problems.push(`${at}: the list of themes lacks ${unlisted.join(', ')}, a file of themes/. Add the name to "var themes".`);
  if (fileless.length) problems.push(`${at}: the list of themes names ${fileless.join(', ')}, with no file in themes/. Remove the name from "var themes".`);
  return problems;
}

function check(staged) {
  const src = (p) => readSource(p, { staged });
  const where = staged ? 'staged' : 'working tree';
  const text = src('DESIGN.md');
  if (text === null) return [`DESIGN.md is not in the ${where}.`];
  const { front } = readDesign(text);
  const problems = [...frontProblems(front), ...packageProblems(src('package.json'))];
  if (problems.length) return problems;
  const want = render(front);
  const fix = staged ? 'Run "npm run theme", then stage the file.' : 'Run "npm run theme".';
  if (src('themes/default.css') !== want.theme) problems.push(`themes/default.css (${where}) differs from the front matter of DESIGN.md. ${fix}`);
  if (src('stack.css') !== want.stack) problems.push(`stack.css (${where}) differs from the front matter of DESIGN.md. ${fix}`);
  problems.push(...motionProblems(front, src('stack.css')).map((p) => `${p} ${fix}`));
  if (src('stack-plain.css') !== want.plain) problems.push(`stack-plain.css (${where}) differs from the front matter of DESIGN.md. ${fix}`);
  if (src('chart-patterns.svg') !== want.patterns) problems.push(`chart-patterns.svg (${where}) differs from chart-patterns in the front matter of DESIGN.md. ${fix}`);
  if (src(VALUES) !== want.values) problems.push(`${VALUES} (${where}) differs from the front matter of DESIGN.md. ${fix}`);
  const base = parseThemeCss(want.theme, 'themes/default.css');
  problems.push(...previewThemeProblems(src('preview/src/app.html'), themeFiles(staged)));
  for (const file of themeFiles(staged)) {
    if (file === 'themes/default.css') continue;
    const css = src(file);
    if (css === null) continue;
    let t;
    try {
      t = parseThemeCss(css, file);
    } catch (e) {
      problems.push(e.message);
      continue;
    }
    for (const d of diffNames(base, t)) {
      const sel = d.block === 'root' ? ':root' : '.dark';
      if (d.missing.length) problems.push(`${file} ${sel} lacks --${d.missing.join(', --')}.`);
      if (d.extra.length) problems.push(`${file} ${sel} has names that themes/default.css lacks: --${d.extra.join(', --')}.`);
    }
  }
  return problems;
}

function main(argv) {
  if (argv.includes('--check')) {
    const problems = check(argv.includes('--staged'));
    for (const p of problems) console.error(`theme check: ${p}`);
    if (!problems.length) console.log(`theme check: themes/default.css, stack.css, stack-plain.css, chart-patterns.svg and ${VALUES} match DESIGN.md, every key of motion has its variable in stack.css, every theme file has the same names, and the list of themes in preview/src/app.html matches themes/.`);
    return problems.length ? 1 : 0;
  }
  const text = readSource('DESIGN.md');
  if (text === null) throw new Error('DESIGN.md not found. Run this from the root of the repository.');
  const { front } = readDesign(text);
  const problems = frontProblems(front);
  if (problems.length) {
    for (const p of problems) console.error(`theme: ${p}`);
    return 1;
  }
  const out = render(front);
  mkdirSync('themes', { recursive: true });
  writeFileSync('themes/default.css', out.theme);
  writeFileSync('stack.css', out.stack);
  writeFileSync('stack-plain.css', out.plain);
  writeFileSync('chart-patterns.svg', out.patterns);
  writeFileSync(VALUES, out.values);
  console.log(`theme: wrote themes/default.css, stack.css, stack-plain.css, chart-patterns.svg and ${VALUES}`);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (e) {
    console.error(`theme: ${e.message}`);
    process.exitCode = 1;
  }
}
